from __future__ import annotations
import math
from typing import Iterable

def shallow_square_approx(h: float, x: float) -> float:
    """Stably evaluate 2(exp(h*x)-1-h*x)/h**2."""
    if not 0.0 < h <= 1.0:
        raise ValueError("require 0 < h <= 1")
    u = h * x
    return 2.0 * (math.expm1(u) - u) / (h * h)

def sampled_uniform_error(n: int, points: int = 20001) -> tuple[float, float]:
    """Return (sampled maximum error, certified continuum bound)."""
    if n < 1 or points < 2:
        raise ValueError("n >= 1 and points >= 2 are required")
    h = 1.0 / n
    error = max(
        abs(shallow_square_approx(h, x) - x * x)
        for x in (j / (points - 1) for j in range(points))
    )
    return error, 4.0 / (9.0 * n)
